       "movaps  %%xmm5,32(%1)\n" \
       "movaps  %%xmm7,48(%1)\n" \
       ""::"r"(state->mt+i),"r"(state->out+i),"r"(mt19937_sse_consts),"r"(i));
}

__host__ void mt19937_sse_genRand624(mt19937_sse_state* state){int i;
  mt19937_sse_do16all(0,state); 
  asm("movl 2500(%0),%%eax; movl %%eax,2496(%0)"::"r"(state->mt):"%eax");
  for(i=16;i<mt19937_N;i+=16) mt19937_sse_do16all(i,state);
}

__host__ unsigned int mt19937_sse_generate_(mt19937_sse_state* state){int i;
   if(state->mti>=mt19937_N) { 
     mt19937_sse_do16all(0,state); 
     asm("movl 2500(%0),%%eax; movl %%eax,2496(%0)"::"r"(state->mt):"%eax");
     for(i=16;i<mt19937_N;i+=16) mt19937_sse_do16all(i,state);
     state->mti=0; 
   }
   return state->out[state->mti++];
}

__device__ __host__ void mt19937_get_sse_state_(mt19937_state* state, mt19937_sse_state* sse_state){
  int i; unsigned y;
  sse_state->mt=sse_state->mt_aligned+3;
  for(i=0;i<mt19937_N;i++){ 
    sse_state->mt[i+mt19937_N+1]=sse_state->mt[i]=y=state->mt[i];
    y ^= (y >> 11);
    y ^= (y << 7) & 0x9d2c5680UL;
    y ^= (y << 15) & 0xefc60000UL;
    y ^= (y >> 18);
    sse_state->out[i]=y;
  }
  sse_state->mti=state->mti;
}

__device__ __host__ void mt19937_init_genrand(mt19937_state* state,unsigned s)
{
    state->mti=mt19937_N+1;
    state->mt[0]= s & 0xffffffffUL;
    for (state->mti=1; state->mti<mt19937_N; state->mti++) {
        state->mt[state->mti] =
    (1812433253UL * (state->mt[state->mti-1] ^ (state->mt[state->mti-1] >> 30)) + state->mti);
        /* See Knuth TAOCP Vol2. 3rd Ed. P.106 for multiplier. */
        /* In the previous versions, MSBs of the seed affect   */
        /* only MSBs of the array mt[].                        */
        /* 2002/01/09 modified by Makoto Matsumoto             */
    state->mt[state->mti] &= 0xffffffffUL;
        /* for >32 bit machines */
    }
}

__device__ __host__ void mt19937_init_by_array(mt19937_state* state,unsigned init_key[], int key_length)
{
    int i, j, k;
    mt19937_init_genrand(state,19650218UL);
    i=1; j=0;
    k = (mt19937_N>key_length ? mt19937_N : key_length);
    for (; k; k--) {
        state->mt[i] = (state->mt[i] ^ ((state->mt[i-1] ^ (state->mt[i-1] >> 30)) * 1664525UL))
          + init_key[j] + j; /* non linear */
        state->mt[i] &= 0xffffffffUL; /* for WORDSIZE > 32 machines */
        i++; j++;
        if (i>=mt19937_N) { state->mt[0] = state->mt[mt19937_N-1]; i=1; }
        if (j>=key_length) j=0;
    }
    for (k=mt19937_N-1; k; k--) {
        state->mt[i] = (state->mt[i] ^ ((state->mt[i-1] ^ (state->mt[i-1] >> 30)) * 1566083941UL))
          - i; /* non linear */
        state->mt[i] &= 0xffffffffUL; /* for WORDSIZE > 32 machines */
        i++;
        if (i>=mt19937_N) { state->mt[0] = state->mt[mt19937_N-1]; i=1; }
    }

    state->mt[0] = 0x80000000UL; /* MSB is 1; assuring non-zero initial array */
}

__device__ __host__ unsigned mt19937_generate_(mt19937_state* state)
{
    unsigned y;

    if (state->mti >= mt19937_N) { /* generate N words at one time */
        int kk;

        if (state->mti == mt19937_N+1)   /* if init_genrand() has not been called, */
            mt19937_init_genrand(state,5489UL); /* a default initial seed is used */

        for (kk=0;kk<mt19937_N-mt19937_M;kk++) {
            y = (state->mt[kk]&mt19937_UPPER_MASK)|(state->mt[kk+1]&mt19937_LOWER_MASK);
            state->mt[kk] = state->mt[kk+mt19937_M] ^ (y >> 1) ^ ((y & 0x1UL)?mt19937_MATRIX_A:0);
        }
        for (;kk<mt19937_N-1;kk++) {
            y = (state->mt[kk]&mt19937_UPPER_MASK)|(state->mt[kk+1]&mt19937_LOWER_MASK);
            state->mt[kk] = state->mt[kk+(mt19937_M-mt19937_N)] ^ (y >> 1) ^ ((y & 0x1UL)?mt19937_MATRIX_A:0);
        }
        y = (state->mt[mt19937_N-1]&mt19937_UPPER_MASK)|(state->mt[0]&mt19937_LOWER_MASK);
        state->mt[mt19937_N-1] = state->mt[mt19937_M-1] ^ (y >> 1) ^ ((y & 0x1UL)?mt19937_MATRIX_A:0);

        state->mti = 0;
    }

    y = state->mt[state->mti++];

    /* Tempering */
    y ^= (y >> 11);
    y ^= (y << 7) & 0x9d2c5680UL;
    y ^= (y << 15) & 0xefc60000UL;
    y ^= (y >> 18);

    return y;
}

__device__ __host__ float mt19937_generate_uniform_float_(mt19937_state* state)
{
    unsigned y;

    if (state->mti >= mt19937_N) { /* generate N words at one time */
        int kk;

        if (state->mti == mt19937_N+1)   /* if init_genrand() has not been called, */
            mt19937_init_genrand(state,5489UL); /* a default initial seed is used */

        for (kk=0;kk<mt19937_N-mt19937_M;kk++) {
            y = (state->mt[kk]&mt19937_UPPER_MASK)|(state->mt[kk+1]&mt19937_LOWER_MASK);
            state->mt[kk] = state->mt[kk+mt19937_M] ^ (y >> 1) ^ ((y & 0x1UL)?mt19937_MATRIX_A:0);
        }
        for (;kk<mt19937_N-1;kk++) {
            y = (state->mt[kk]&mt19937_UPPER_MASK)|(state->mt[kk+1]&mt19937_LOWER_MASK);
            state->mt[kk] = state->mt[kk+(mt19937_M-mt19937_N)] ^ (y >> 1) ^ ((y & 0x1UL)?mt19937_MATRIX_A:0);
        }
        y = (state->mt[mt19937_N-1]&mt19937_UPPER_MASK)|(state->mt[0]&mt19937_LOWER_MASK);
        state->mt[mt19937_N-1] = state->mt[mt19937_M-1] ^ (y >> 1) ^ ((y & 0x1UL)?mt19937_MATRIX_A:0);

        state->mti = 0;
    }

    y = state->mt[state->mti++];

    /* Tempering */
    y ^= (y >> 11);
    y ^= (y << 7) & 0x9d2c5680UL;
    y ^= (y << 15) & 0xefc60000UL;
    y ^= (y >> 18);

    return y *  2.3283064365386963e-10;
}

__device__ __host__ void mt19937_init_(mt19937_state* state){
    unsigned init[4]={0x123,0x234,0x345,0x456}, length=4;
    mt19937_init_by_array(state,init,length); mt19937_generate_(state); state->mti=0;
}

__device__ __host__ void mt19937_Transition(mt19937_state* state){
  int i; unsigned y,temp;
  y = (state->mt[0]&mt19937_UPPER_MASK)|(state->mt[1]&mt19937_LOWER_MASK);
  temp = state->mt[mt19937_M] ^ (y >> 1) ^ ((y & 0x1UL)?mt19937_MATRIX_A:0);
  for(i=0;i<mt19937_N-1;i++) state->mt[i]=state->mt[i+1];
  state->mt[mt19937_N-1] = temp;
}

__device__ __host__ void mt19937_SkipAheadWithPolynomial(mt19937_state* state, unsigned* poly){
  int i,j; mt19937_state out_state;
  for(j=0;j<mt19937_N;j++) out_state.mt[j]=0;
  for(i=19936;i>=0;i--){
    mt19937_Transition(&out_state);
    if((poly[i/32]>>(i%32))&1)
      for(j=0;j<mt19937_N;j++) out_state.mt[j]^=state->mt[j];
  }
  for(j=0;j<mt19937_N;j++) state->mt[j]=out_state.mt[j];
}

__device__ void mt19937_dev_skipahead_(mt19937_state* state,unsigned long long offset0,unsigned offset_log){
  int i;     // the function skips ahead N=(offset0*2^offset_log) numbers, N < 2^512
  for(i=0;i<64;i++) if((offset0>>i)&1) mt19937_SkipAheadWithPolynomial(state,(unsigned *)mt19937_pp[offset_log+i]);
}

__host__ void mt19937_skipahead_(mt19937_state* state, unsigned long long offset0,unsigned offset_log){
  int i;     // the function skips ahead N=(offset0*2^offset_log) numbers, N < 2^512
  for(i=0;i<64;i++) if((offset0>>i)&1) mt19937_SkipAheadWithPolynomial(state,mt19937__pp[offset_log+i]);
}

__device__ void mt19937_dev_init_sequence_(mt19937_state* state,unsigned long long SequenceNumber){ 
  mt19937_init_(state);                                           // 0 <= SequenceNumber <  10^19
  mt19937_dev_skipahead_(state,SequenceNumber,440U);       // length of each sequence  <  10^130
}

__host__ void mt19937_init_sequence_(mt19937_state* state,unsigned long long SequenceNumber){ 
  mt19937_init_(state);                                           // 0 <= SequenceNumber <  10^19
  mt19937_skipahead_(state,SequenceNumber,440U);       // length of each sequence  <  10^130
}

__host__ void mt19937_print_state_(mt19937_state* state){
   int i; printf("Generator State: {");
   for(i=0;i<mt19937_N;i++){ printf("%u",state->mt[i]); if(i<mt19937_N-1) printf(",");}
   printf("}\n");
}

__device__ unsigned ArrayZero[20657];

__global__ void mt19937_kernel_FillInArrayZero(mt19937_state* state){ // use configuration <<<1,227>>>
    unsigned a,b,c,d,e,y,i;  long repeats;
    mt19937_state mystate=*state;
    __shared__ unsigned int values[mt19937_NPLUSL];
    a = threadIdx.x%mt19937_L;
    i=a;          values[i]=mystate.mt[i];
    i+=mt19937_L; values[i]=mystate.mt[i];
    i+=mt19937_L; if(i<mt19937_N) values[i]=mystate.mt[i];
    __syncthreads();
    b = a+1; c = a+mt19937_M; d = a+mt19937_N; e = a;
    for(repeats=0;repeats<91;repeats++){
      ArrayZero[e] = values[a];
      y = (values[a]&mt19937_UPPER_MASK)|(values[b]&mt19937_LOWER_MASK);
      values[d]=values[c] ^ (y>>1) ^ ((y&1U)?mt19937_MATRIX_A:0);
      a+=mt19937_L; b+=mt19937_L; c+=mt19937_L; d+=mt19937_L; e+=mt19937_L;
      if(a>=mt19937_NPLUSL) a-=mt19937_NPLUSL;
      if(b>=mt19937_NPLUSL) b-=mt19937_NPLUSL;
      if(c>=mt19937_NPLUSL) c-=mt19937_NPLUSL;
      if(d>=mt19937_NPLUSL) d-=mt19937_NPLUSL;
      __syncthreads();
    }
}

__global__ void mt19937_kernel_generate_array(mt19937_state* state, unsigned (*p)[10][128][624],unsigned int* pshift, unsigned int* out, long* length) {
    // each mt19937_L threads fill in "length" values in the output array
    unsigned index,a,b,c,d,e,y,xi,p_shift; long repeats; unsigned* poly;
    unsigned long offset; 
    __shared__ unsigned int values[mt19937_NPLUSL];
    index  = (threadIdx.x + blockIdx.x * blockDim.x); p_shift=(*pshift);
    a = index%mt19937_L; offset = (index-a)/mt19937_L*(*length);
    if(offset>0){ //  ! Skip ahead offset bytes ! using polynomial coefficients from (*p) !
       poly=(*p)[p_shift-15][offset>>p_shift];     // ! length should be divisible by 2^pshift !
       values[a]=values[a+227]=0; if(a<170) values[a+454]=0;
       for(xi=0;xi<19937;xi++)
         if((poly[xi/32]>>(xi%32))&1){
           values[a]^=ArrayZero[xi+a];
           values[a+227]^=ArrayZero[xi+a+227];
           if(a<170) values[a+454]^=ArrayZero[xi+a+454];
         }
    } else{ values[a]=state->mt[a]; values[a+227]=state->mt[a+227]; if(a<170)values[a+454]=state->mt[a+454];}
    __syncthreads();
    b = a+1; c = a+mt19937_M; d = a+mt19937_N; e = offset+a;
    for(repeats=0;repeats<(*length)/mt19937_L+1;repeats++){
      y  =  values[a];
      y ^= (y >> 11);
      y ^= (y << 7) & 0x9d2c5680U;
      y ^= (y << 15) & 0xefc60000U;
      y ^= (y >> 18);
      if(e<(offset+(*length))) out[e] = y;
      y = (values[a]&mt19937_UPPER_MASK)|(values[b]&mt19937_LOWER_MASK);
      values[d]=values[c] ^ (y>>1) ^ ((y&1U)?mt19937_MATRIX_A:0);
      a+=mt19937_L; b+=mt19937_L; c+=mt19937_L; d+=mt19937_L; e+=mt19937_L;
      if(a>=mt19937_NPLUSL) a-=mt19937_NPLUSL;
      if(b>=mt19937_NPLUSL) b-=mt19937_NPLUSL;
      if(c>=mt19937_NPLUSL) c-=mt19937_NPLUSL;
      if(d>=mt19937_NPLUSL) d-=mt19937_NPLUSL;
      __syncthreads();
    }
}

__host__ void mt19937_generate_gpu_array_(mt19937_state* state, unsigned int* dev_out, long length){

   long   mylength; unsigned t,i;       // It is supposed here that mt19937_ARRAY_SECTIONS=64
   mt19937_state*    dev_state;         // mylength is the least possible integer such that 
   long*             dev_length;        // mylength is divisible by 2^i   and   length <= (mylength*64)
   unsigned*         dev_pshift;

   t=2147483648U; i=25; while((length<=t)&&(i>0)){ t=(t>>1); i--;}  // i satisfies: 2^(i+6) < length <= 2^(i+7)
   if(i<15) { i=15; mylength=32768;}                                // if i<15 then we use i=15, length=2^21
   else if(i>24) {i=24; mylength=33554432;}                         // if i>24 then we use i=24, length=2^31
   else { mylength=length>>(i+6); if((mylength<<(i+6))<length) mylength++; mylength = (mylength<<i);}

   mt19937_CUDA_CALL(cudaMalloc((void**)&dev_state,sizeof(mt19937_state)));
   mt19937_CUDA_CALL(cudaMalloc((void**)&dev_length,sizeof(long)));
   mt19937_CUDA_CALL(cudaMalloc((void**)&dev_pshift,sizeof(unsigned)));
   mt19937_CUDA_CALL(cudaMemcpy(dev_state,state,sizeof(mt19937_state),cudaMemcpyHostToDevice));
   mt19937_CUDA_CALL(cudaMemcpy(dev_length,&mylength,sizeof(long),cudaMemcpyHostToDevice));
   mt19937_CUDA_CALL(cudaMemcpy(dev_pshift,&i,sizeof(unsigned),cudaMemcpyHostToDevice));

   mt19937_kernel_FillInArrayZero<<<1,227>>>(dev_state);
   mt19937_kernel_generate_array<<<mt19937_BLOCKS,mt19937_THREADS>>>(dev_state,mt19937_p15_24,dev_pshift,dev_out,dev_length);
   mt19937_CUDA_CALL(cudaGetLastError());

   mt19937_CUDA_CALL(cudaFree(dev_state)); mt19937_CUDA_CALL(cudaFree(dev_length));  mt19937_CUDA_CALL(cudaFree(dev_pshift));
}

__global__ void mt19937_kernel_generate_array_float(mt19937_state* state, unsigned (*p)[10][128][624],unsigned int* pshift, float* out, long* length) {
    // each mt19937_L threads fill in "length" values in the output array
    unsigned index,a,b,c,d,e,y,xi,p_shift; long repeats; unsigned* poly;
    unsigned long offset; 
    __shared__ unsigned int values[mt19937_NPLUSL];
    index  = (threadIdx.x + blockIdx.x * blockDim.x); p_shift=(*pshift);
    a = index%mt19937_L; offset = (index-a)/mt19937_L*(*length);
    if(offset>0){ //  ! Skip ahead offset bytes ! using polynomial coefficients from (*p) !
       poly=(*p)[p_shift-15][offset>>p_shift];     // ! length should be divisible by 2^pshift !
       values[a]=values[a+227]=0; if(a<170) values[a+454]=0;
       for(xi=0;xi<19937;xi++)
         if((poly[xi/32]>>(xi%32))&1){
           values[a]^=ArrayZero[xi+a];
           values[a+227]^=ArrayZero[xi+a+227];
           if(a<170) values[a+454]^=ArrayZero[xi+a+454];
         }
    } else{ values[a]=state->mt[a]; values[a+227]=state->mt[a+227]; if(a<170)values[a+454]=state->mt[a+454];}
    __syncthreads();
    b = a+1; c = a+mt19937_M; d = a+mt19937_N; e = offset+a;
    for(repeats=0;repeats<(*length)/mt19937_L+1;repeats++){
      y  =  values[a];
      y ^= (y >> 11);
      y ^= (y << 7) & 0x9d2c5680U;
      y ^= (y << 15) & 0xefc60000U;
      y ^= (y >> 18);
      if(e<(offset+(*length))) out[e] = ((float)y) * 2.3283064365386963e-10;
      y = (values[a]&mt19937_UPPER_MASK)|(values[b]&mt19937_LOWER_MASK);
      values[d]=values[c] ^ (y>>1) ^ ((y&1U)?mt19937_MATRIX_A:0);
      a+=mt19937_L; b+=mt19937_L; c+=mt19937_L; d+=mt19937_L; e+=mt19937_L;
      if(a>=mt19937_NPLUSL) a-=mt19937_NPLUSL;
      if(b>=mt19937_NPLUSL) b-=mt19937_NPLUSL;
      if(c>=mt19937_NPLUSL) c-=mt19937_NPLUSL;
      if(d>=mt19937_NPLUSL) d-=mt19937_NPLUSL;
      __syncthreads();
    }
}

__host__ void mt19937_generate_gpu_array_float_(mt19937_state* state, float* dev_out, long length){

   long   mylength; unsigned t,i;       // It is supposed here that mt19937_ARRAY_SECTIONS=64
   mt19937_state*    dev_state;         // mylength is the least possible integer such that 
   long*             dev_length;        // mylength is divisible by 2^i   and   length <= (mylength*64)
   unsigned*         dev_pshift;

   t=2147483648U; i=25; while((length<=t)&&(i>0)){ t=(t>>1); i--;}  // i satisfies: 2^(i+6) < length <= 2^(i+7)
   if(i<15) { i=15; mylength=32768;}                                // if i<15 then we use i=15, length=2^21
   else if(i>24) {i=24; mylength=33554432;}                         // if i>24 then we use i=24, length=2^31
   else { mylength=length>>(i+6); if((mylength<<(i+6))<length) mylength++; mylength = (mylength<<i);}

   mt19937_CUDA_CALL(cudaMalloc((void**)&dev_state,sizeof(mt19937_state)));
   mt19937_CUDA_CALL(cudaMalloc((void**)&dev_length,sizeof(long)));
   mt19937_CUDA_CALL(cudaMalloc((void**)&dev_pshift,sizeof(unsigned)));
   mt19937_CUDA_CALL(cudaMemcpy(dev_state,state,sizeof(mt19937_state),cudaMemcpyHostToDevice));
   mt19937_CUDA_CALL(cudaMemcpy(dev_length,&mylength,sizeof(long),cudaMemcpyHostToDevice));
   mt19937_CUDA_CALL(cudaMemcpy(dev_pshift,&i,sizeof(unsigned),cudaMemcpyHostToDevice));

   mt19937_kernel_FillInArrayZero<<<1,227>>>(dev_state);
   mt19937_kernel_generate_array_float<<<mt19937_BLOCKS,mt19937_THREADS>>>(dev_state,mt19937_p15_24,dev_pshift,dev_out,dev_length);
   mt19937_CUDA_CALL(cudaGetLastError());

   mt19937_CUDA_CALL(cudaFree(dev_state)); mt19937_CUDA_CALL(cudaFree(dev_length));  mt19937_CUDA_CALL(cudaFree(dev_pshift));
}

